#include <iostream>
#include <string>

using namespace std;

string calculateGrade(double averageMarks) {
    if (averageMarks >= 91 && averageMarks <= 100) {
        return "A+";
    } else if (averageMarks >= 81 && averageMarks < 91) {
        return "A-";
    } else if (averageMarks >= 71 && averageMarks < 81) {
        return "B+";
    } else if (averageMarks >= 61 && averageMarks < 71) {
        return "B-";
    } else if (averageMarks >= 51 && averageMarks < 61) {
        return "C";
    } else if (averageMarks >= 41 && averageMarks < 51) {
        return "D";
    } else if (averageMarks >= 35 && averageMarks < 41) {
        return "E";
    } else {
        return "Fail";
    }
}

int main() {
    string vuID;
    double csMarks, mathMarks, pakStudyMarks, mgtMarks;

    cout << "\n";
    cout << " Enter your VU-ID:\n";
    cin >> vuID;

    cout << " Enter Marks of CS:\n ";
    cin >> csMarks;
    cout << " Enter Marks of Math:\n ";
    cin >> mathMarks;
    cout << " Enter Marks of Pak Study:\n ";
    cin >> pakStudyMarks;
    cout << " Enter Marks of MGT:\n ";
    cin >> mgtMarks;

    double totalMarks = csMarks + mathMarks + pakStudyMarks + mgtMarks;
    double averageMarks = totalMarks / 4;

    cout << "\n VU ID: " << vuID << endl;
    cout << " Total Marks: " << totalMarks << endl;
    cout << " Average Marks: " << averageMarks << endl;
    cout << " Grade: " << calculateGrade(averageMarks) << endl;

    return 0;
}
